package com.dennis.aimasteringlab;
import java.io.*;
/** Writes one deterministic v0.9 fixture per invocation. */
public final class V09FixtureGenerator{
 private static final int RATE=48000;public static void main(String[]a)throws Exception{if(a.length!=2)throw new IllegalArgumentException();String k=a[0];int sec=(k.equals("source")||k.equals("reference")||k.equals("artificial"))?42:20;File f=new File(a[1]);if(f.getParentFile()!=null)f.getParentFile().mkdirs();try(OutputStream o=new BufferedOutputStream(new FileOutputStream(f),262144)){header(o,(long)RATE*sec);for(long n=0;n<(long)RATE*sec;n++){double[]v=signal(k,n/(double)RATE,sec);write(o,q(v[0],k.equals("artificial")));write(o,q(v[1],k.equals("artificial")));}}System.out.println(k.toUpperCase()+" "+Hashing.sha256(f));}
 private static double[]signal(String k,double t,int d){double edge=smooth(Math.min(1,t/.65))*smooth(Math.min(1,(d-t)/1.8));if(k.equals("polarity")){double m=technical(t);return new double[]{edge*m,-edge*m};}if(k.equals("delay"))return new double[]{edge*technical(t),edge*technical(Math.max(0,t-6.0/RATE))};double m=.050*Math.sin(w(92,t,.2))+.045*Math.sin(w(280,t,.7))+.052*Math.sin(w(880,t,.4))+.044*Math.sin(w(1800,t,.9))+.032*Math.sin(w(3100,t,.3))+.017*Math.sin(w(6500,t,1.1))+.008*Math.sin(w(11000,t,.6)),s=.010*Math.sin(w(430,t,.1))+.008*Math.sin(w(1350,t,.8))+.006*Math.sin(w(4700,t,.5));if(k.equals("reference")){m=.038*Math.sin(w(92,t,.2))+.036*Math.sin(w(280,t,.7))+.060*Math.sin(w(880,t,.4))+.074*Math.sin(w(1800,t,.9))+.054*Math.sin(w(3100,t,.3))+.024*Math.sin(w(6500,t,1.1))+.010*Math.sin(w(11000,t,.6));s*=.55;}if(k.equals("hum")||k.equals("source")||k.equals("artificial"))m+=.026*Math.sin(w(50,t,0))+.021*Math.sin(w(100,t,.4))+.017*Math.sin(w(150,t,.7))+.013*Math.sin(w(200,t,.2));if(k.equals("source")||k.equals("artificial"))m+=.006*Math.sin(w(8125,t,.1))+.004*Math.sin(w(16250,t,.5));if(k.equals("single"))m+=.010*Math.sin(w(11000,t,.1));if(k.equals("buzz"))m+=.020*Math.sin(w(812.5,t,.1))+.016*Math.sin(w(1625,t,.4))+.012*Math.sin(w(2437.5,t,.7))+.009*Math.sin(w(3250,t,.2));if(k.equals("source")||k.equals("artificial")){double x=plateau(t,7.9,8.5,.035);m+=x*(.23*Math.sin(w(62,t,.3))+.17*Math.sin(w(125,t,.9)));x=plateau(t,13,13.7,.035);s+=x*(.18*Math.sin(w(740,t,.2))+.15*Math.sin(w(2050,t,.6))+.11*Math.sin(w(3900,t,1)));x=plateau(t,18,18.6,.03);m+=x*(.19*Math.sin(w(5100,t,.4))+.15*Math.sin(w(6000,t,.8)));}double l=edge*(m+s),r=edge*(m-s);if(k.equals("source")||k.equals("artificial"))l*=Math.pow(10,.9/20);return new double[]{l,r};}
 private static double technical(double t){return .055*Math.sin(w(503,t,.2))+.045*Math.sin(w(3011,t,.6))+.038*Math.sin(w(7013,t,.9))+.030*Math.sin(w(11027,t,.4));}private static double w(double f,double t,double p){return 2*Math.PI*f*t+p;}private static double plateau(double t,double a,double b,double r){if(t<=a||t>=b)return 0;return smooth(Math.min(Math.min(1,(t-a)/r),Math.min(1,(b-t)/r)));}private static double smooth(double x){x=Math.max(0,Math.min(1,x));return x*x*(3-2*x);}private static int q(double v,boolean sixteen){if(sixteen){int x=(int)Math.max(-32768,Math.min(32767,Math.round(v*32768)));return x<<8;}return(int)Math.max(-8388608,Math.min(8388607,Math.round(v*8388608)));}private static void write(OutputStream o,int v)throws IOException{o.write(v&255);o.write((v>>>8)&255);o.write((v>>>16)&255);}private static void header(OutputStream o,long f)throws IOException{long b=f*6;LittleEndian.writeAscii(o,"RIFF");LittleEndian.writeU32(o,36+b);LittleEndian.writeAscii(o,"WAVE");LittleEndian.writeAscii(o,"fmt ");LittleEndian.writeU32(o,16);LittleEndian.writeU16(o,1);LittleEndian.writeU16(o,2);LittleEndian.writeU32(o,RATE);LittleEndian.writeU32(o,RATE*6L);LittleEndian.writeU16(o,6);LittleEndian.writeU16(o,24);LittleEndian.writeAscii(o,"data");LittleEndian.writeU32(o,b);}
}
